import { getTextWidth } from '../../../../../../typography/utils.js';
import { ItemFontStyles } from '../components/ChartLegendItem/ChartLegendItem.sty.js';
import {
  ITEM_HEIGHT,
  LEGEND_BUTTON_WIDTH,
  MIN_ITEM_WIDTH,
  VIRTUALIZED_GRID_THRESHOLD,
} from '../constants.js';
import { findIndexOfMinMaxString } from '../functions/find-index-of-min-max-string.js';
import { GridSettings } from '../types/legend-internal.js';
import { LegendItem } from '../types/legend.js';

const getMinMaxSeriesWidth = (items: LegendItem[]) => {
  const { longest: longestSeriesIndex, shortest: shortestSeriesIndex } =
    findIndexOfMinMaxString(items);
  const longestSeriesName =
    longestSeriesIndex !== -1 ? items[longestSeriesIndex].name : '';

  const shortestSeriesName =
    shortestSeriesIndex !== -1 ? items[shortestSeriesIndex].name : '';

  const longestSeries =
    getTextWidth(longestSeriesName, ItemFontStyles) + LEGEND_BUTTON_WIDTH;

  const shortestSeries =
    getTextWidth(shortestSeriesName, ItemFontStyles) + LEGEND_BUTTON_WIDTH;

  return {
    shortestSeries,
    longestSeries,
  };
};

export const buildGridSettings = (
  items: LegendItem[],
  width: number,
  height: number,
): GridSettings => {
  const { shortestSeries, longestSeries } = getMinMaxSeriesWidth(items);

  const maxRowsCanFitTheContainer = Math.floor(height / ITEM_HEIGHT.value);
  const maxColumnsCanFitTheContainer = Math.max(
    Math.floor(width / MIN_ITEM_WIDTH),
    1,
  );

  const minItemWidth = Math.min(
    Math.max(shortestSeries, MIN_ITEM_WIDTH),
    width,
  );
  const maxItemWidth = Math.min(Math.max(longestSeries, MIN_ITEM_WIDTH), width);

  const maxItemsPerRow = Math.floor(width / maxItemWidth);
  const maxNrOfSeriesTruncated = maxItemsPerRow * maxRowsCanFitTheContainer;

  const canFitAllItemsWithoutScrollbar = maxNrOfSeriesTruncated >= items.length;

  return {
    maxRows: maxRowsCanFitTheContainer,
    maxColumns: maxColumnsCanFitTheContainer,
    minItemWidth,
    maxItemWidth,
    canFitAllItemsWithoutScrollbar,
    hasVirtual:
      !canFitAllItemsWithoutScrollbar &&
      items.length > VIRTUALIZED_GRID_THRESHOLD,
    longestSeries: longestSeries,
  };
};
